int depthOf(const Layer* n){int d=0;for(auto p=n->parent;p;p=p->parent)++d;return d;}
int nameLeft(const Layer* n,bool thumbnails){return 12+depthOf(n)*24+24+(n->group||!thumbnails?40:88);}
static void checker(QPainter& p,QRect r,int side,QColor a,QColor b){p.save();p.setClipRect(r);p.fillRect(r,a);for(int y=r.top();y<r.bottom()+1;y+=side)for(int x=r.left();x<r.right()+1;x+=side)if(((x-r.left())/side+(y-r.top())/side)%2==0)p.fillRect(QRect(x,y,side,side),b);p.restore();}
static void drawIcon(QPainter& painter,QRect rect,const QString& name,QColor color){
    static QHash<QString,std::shared_ptr<QSvgRenderer>> cache;
    QString key=name+color.name(QColor::HexArgb);
    auto renderer=cache.value(key);
    if(!renderer){QFile file(":/icons/"+name+".svg");if(!file.open(QIODevice::ReadOnly))return;auto svg=file.readAll();svg.replace("<svg",QByteArray("<svg fill=\"")+color.name().toUtf8()+"\"");renderer=std::make_shared<QSvgRenderer>(svg);renderer->setAspectRatioMode(Qt::KeepAspectRatio);cache.insert(key,renderer);}
    QPointF center=QRectF(rect).center();renderer->render(&painter,QRectF(center.x()-7,center.y()-7,14,14));
}
void drawEye(QPainter& p,QRect r,bool visible,QColor color){drawIcon(p,r,visible?"eye":"hidden",color);}
void drawFolder(QPainter& p,QRect r,bool opened,QColor color){drawIcon(p,r,opened?"folderOpen":"folder",color);}
QIcon glyph(QString kind,QColor color,bool state){
    if(kind=="eye")kind=state?"eye":"hidden";
    else if(kind=="expand")kind=state?"collapse":"expand";
    else if(kind=="folder")kind=state?"folderOpen":"folder";
    else if(kind=="check")kind=state?"checked":"check";
    QIcon icon;for(int ratio:{1,2,3,4}){QPixmap pixmap(24*ratio,24*ratio);pixmap.setDevicePixelRatio(ratio);pixmap.fill(Qt::transparent);QPainter painter(&pixmap);painter.setRenderHint(QPainter::Antialiasing);drawIcon(painter,QRect(0,0,24,24),kind,color);painter.end();icon.addPixmap(pixmap);}return icon;
}
QModelIndex LayerModel::index(int row,int col,const QModelIndex& p)const{if(!doc||col||row<0)return {};auto& nodes=p.isValid()?static_cast<Layer*>(p.internalPointer())->children:doc->roots;if(row>=int(nodes.size()))return {};return createIndex(row,col,nodes[row].get());}
QModelIndex LayerModel::parent(const QModelIndex& i)const{if(!i.isValid())return {};return forNode(static_cast<Layer*>(i.internalPointer())->parent);}
int LayerModel::rowCount(const QModelIndex& p)const{if(!doc||p.column()>0)return 0;return int((p.isValid()?static_cast<Layer*>(p.internalPointer())->children:doc->roots).size());}
QModelIndex LayerModel::forNode(Layer* n)const{if(!doc||!n)return {};auto& siblings=n->parent?n->parent->children:doc->roots;for(int i=0;i<int(siblings.size());++i)if(siblings[i].get()==n)return createIndex(i,0,n);return {};}
QVariant LayerModel::data(const QModelIndex& i,int role)const{if(!i.isValid())return {};auto n=static_cast<Layer*>(i.internalPointer());if(role==Qt::DisplayRole||role==Qt::EditRole||role==Qt::ToolTipRole)return n->name;return {};}
Qt::ItemFlags LayerModel::flags(const QModelIndex& i)const{if(!i.isValid())return Qt::ItemIsDropEnabled;return Qt::ItemIsEnabled|Qt::ItemIsSelectable|Qt::ItemIsEditable|Qt::ItemIsDragEnabled|Qt::ItemIsDropEnabled;}
bool LayerModel::setData(const QModelIndex& i,const QVariant& value,int role){if(role!=Qt::EditRole||value.toString().trimmed().isEmpty())return false;auto n=static_cast<Layer*>(i.internalPointer());n->name=value.toString().trimmed();n->manual=true;emit dataChanged(i,i);if(renamed)renamed();return true;}
LayerDelegate::LayerDelegate(Window* w):QStyledItemDelegate(w),owner(w){}
QSize LayerDelegate::sizeHint(const QStyleOptionViewItem&,const QModelIndex& i)const{return {200,static_cast<Layer*>(i.internalPointer())->group||!owner->thumbnailsEnabled?28:72};}
void LayerDelegate::paint(QPainter* p,const QStyleOptionViewItem& opt,const QModelIndex& i)const{
    auto n=static_cast<Layer*>(i.internalPointer());QRect r=opt.rect;int x=12+depthOf(n)*24,y=r.center().y();p->save();p->setRenderHint(QPainter::Antialiasing);
    if(n->checked)p->fillRect(r,owner->night?QColor("#485d72"):QColor("#c1d1e0"));
    else if((opt.state&QStyle::State_MouseOver)&&owner->tree->viewport()->mapFromGlobal(QCursor::pos()).x()>=x+24)p->fillRect(QRect(x+24,r.top(),r.right()-x-36,r.height()),owner->night?QColor("#3c3c3c"):QColor("#e6e6e6"));
    p->setPen(owner->border());for(int d=0;d<depthOf(n);++d)p->drawLine(12+d*24+36,r.top(),12+d*24+36,r.bottom());
    drawEye(*p,{x,y-12,24,24},!n->hidden,owner->muted());
    if(n->group){drawFolder(*p,{x+30,y-12,24,24},owner->tree->isExpanded(i),owner->muted());}
    else if(!owner->thumbnailsEnabled){drawIcon(*p,{x+30,y-12,24,24},"layer",owner->muted());}
    else{QRect thumbRect(x+36,y-32,64,64);checker(*p,thumbRect,4,owner->panel(),owner->border());if(auto image=owner->thumb(n)){QSize size=image->size();p->drawImage(QRect(thumbRect.center()-QPoint(size.width()/2,size.height()/2),size),*image);}else if(n->crop.isEmpty()){p->setPen(owner->text());p->setBrush(Qt::NoBrush);p->drawRect(thumbRect.center().x()-4,thumbRect.center().y()-6,8,12);p->drawLine(thumbRect.center()+QPoint(0,-6),thumbRect.center()+QPoint(4,-2));}p->setPen(owner->border());p->setBrush(Qt::NoBrush);p->drawRect(thumbRect.adjusted(0,0,-1,-1));}
    int left=nameLeft(n,owner->thumbnailsEnabled),right=r.right()-12;int originalWidth=n->name!=n->originalName?qMin(90,QFontMetrics(p->font()).horizontalAdvance(n->originalName)):0;
    if(originalWidth){p->setPen(owner->muted());p->drawText(QRect(right-originalWidth,r.top(),originalWidth,r.height()),Qt::AlignVCenter|Qt::AlignRight,QFontMetrics(p->font()).elidedText(n->originalName,Qt::ElideRight,originalWidth));right-=originalWidth+12;}
    p->setPen(owner->text());int max=right-left-12;if(!n->group&&n->crop.isEmpty())max-=110;
    p->drawText(QRect(left,r.top(),qMax(20,max),r.height()),Qt::AlignVCenter|Qt::AlignLeft,QFontMetrics(p->font()).elidedText(n->name,Qt::ElideRight,max));
    if(!n->group&&n->crop.isEmpty()){p->setPen(QColor("#e5484d"));p->drawText(QRect(right-110,r.top(),110,r.height()),Qt::AlignVCenter|Qt::AlignRight,ui("此图层无像素"));}
    if(owner->tree->dropNode==n){p->setPen(QPen(QColor("#5c7c9f"),2));if(owner->tree->dropPlace==0)p->drawRect(r.adjusted(1,1,-2,-2));else p->drawLine(r.left(),owner->tree->dropPlace<0?r.top():r.bottom(),r.right(),owner->tree->dropPlace<0?r.top():r.bottom());}
    p->restore();
}
void LayerDelegate::updateEditorGeometry(QWidget* editor,const QStyleOptionViewItem& opt,const QModelIndex& i)const{int left=nameLeft(static_cast<Layer*>(i.internalPointer()),owner->thumbnailsEnabled);editor->setGeometry(left,opt.rect.center().y()-14,qMax(100,opt.rect.right()-left-30),28);}
LayerView::LayerView(Window* w):QTreeView(w),owner(w){setRootIsDecorated(false);setIndentation(0);setHeaderHidden(true);setItemsExpandable(false);setExpandsOnDoubleClick(false);setEditTriggers(QAbstractItemView::NoEditTriggers);setSelectionMode(QAbstractItemView::NoSelection);setMouseTracking(true);setAcceptDrops(true);setDragDropMode(QAbstractItemView::DragDrop);setDefaultDropAction(Qt::MoveAction);setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);setVerticalScrollMode(QAbstractItemView::ScrollPerPixel);}
void LayerView::mousePressEvent(QMouseEvent* e){
    if(owner->busy||e->button()!=Qt::LeftButton)return;setFocus();dragNode=nullptr;deferredSelection.clear();auto i=indexAt(e->pos());
    if(!i.isValid()){if(!(e->modifiers()&(Qt::ControlModifier|Qt::ShiftModifier))){for(auto n:flatten(owner->doc.roots))n->checked=false;owner->active=nullptr;owner->selectionAnchor.clear();owner->refresh();}return;}
    auto n=static_cast<Layer*>(i.internalPointer());int x=e->pos().x()-(12+depthOf(n)*24);
    if(x>=0&&x<24){owner->visibility(n,!n->hidden);owner->refresh(false,true);return;}
    if(n->group&&x>=30&&x<54){n->opened=!isExpanded(i);setExpanded(i,n->opened);owner->refresh();return;}
    pressed=e->pos();dragNode=n;
    auto flat=flatten(owner->doc.roots);int count=std::count_if(flat.begin(),flat.end(),[](auto node){return node->checked;});
    if(!e->modifiers()&&n->checked&&count>1)deferredSelection=n->id;else owner->selectRow(n,e->modifiers());
}
void LayerView::mouseReleaseEvent(QMouseEvent* e){if(e->button()==Qt::LeftButton){if(!deferredSelection.isEmpty())for(auto n:flatten(owner->doc.roots))if(n->id==deferredSelection){owner->selectRow(n,Qt::NoModifier);break;}deferredSelection.clear();dragNode=nullptr;}QTreeView::mouseReleaseEvent(e);}
void LayerView::mouseDoubleClickEvent(QMouseEvent* e){auto i=indexAt(e->pos());if(!i.isValid()||owner->busy)return;auto n=static_cast<Layer*>(i.internalPointer());int x=e->pos().x()-(12+depthOf(n)*24);if(e->button()!=Qt::LeftButton)return;dragNode=nullptr;deferredSelection.clear();if(n->group&&x>=30&&x<54)return;else if(!n->group&&owner->thumbnailsEnabled&&x>=36&&x<100)owner->preview(n);else if(e->pos().x()>=nameLeft(n,owner->thumbnailsEnabled))edit(i);}
void LayerView::mouseMoveEvent(QMouseEvent* e){
    if(dragNode&&(e->buttons()&Qt::LeftButton)&&(e->pos()-pressed).manhattanLength()>=QApplication::startDragDistance()){
        auto drag=new QDrag(this);auto mime=new QMimeData;QJsonArray ids;
        for(auto n:flatten(owner->doc.roots))if(n->checked){bool ancestorSelected=false;for(auto p=n->parent;p;p=p->parent)if(p->checked)ancestorSelected=true;if(!ancestorSelected)ids.append(n->id);}
        mime->setData("application/x-psd-native-layer",QJsonDocument(ids).toJson(QJsonDocument::Compact));drag->setMimeData(mime);deferredSelection.clear();drag->exec(Qt::MoveAction);dragNode=nullptr;dropNode=nullptr;viewport()->update();
    }else QTreeView::mouseMoveEvent(e);
}
void LayerView::dragEnterEvent(QDragEnterEvent* e){if(e->mimeData()->hasFormat("application/x-psd-native-layer"))e->acceptProposedAction();}
void LayerView::dragMoveEvent(QDragMoveEvent* e){auto i=indexAt(e->position().toPoint());dropNode=i.isValid()?static_cast<Layer*>(i.internalPointer()):nullptr;dropPlace=0;if(dropNode){auto r=visualRect(i);int y=e->position().y()-r.top();dropPlace=y<7?-1:y>r.height()-7?1:dropNode->group?0:1;}e->acceptProposedAction();viewport()->update();}
void LayerView::dropEvent(QDropEvent* e){
    if(!owner->busy&&e->mimeData()->hasFormat("application/x-psd-native-layer")){
        auto ids=QJsonDocument::fromJson(e->mimeData()->data("application/x-psd-native-layer")).array();QVector<Layer*> nodes;for(auto id:ids)for(auto n:flatten(owner->doc.roots))if(n->id==id.toString())nodes.append(n);
        bool valid=!nodes.isEmpty();for(auto n:nodes)if(n==dropNode||owner->contains(n,dropNode))valid=false;
        if(valid){if(dropPlace>=0)std::reverse(nodes.begin(),nodes.end());for(auto n:nodes)owner->move(n,dropNode,dropPlace);e->acceptProposedAction();}
    }dropNode=nullptr;deferredSelection.clear();viewport()->update();
}
void LayerView::keyPressEvent(QKeyEvent* e){if(e->matches(QKeySequence::SelectAll)){for(auto n:flatten(owner->doc.roots))n->checked=true;owner->active=nullptr;owner->refresh();e->accept();}else if(e->key()==Qt::Key_Delete)owner->deleteSelection();else if(e->key()==Qt::Key_F2&&owner->active)edit(owner->model->forNode(owner->active));else QTreeView::keyPressEvent(e);}
