void Window::load(QString path){if(busy)return;canvas->delay.stop();canvas->watcher.waitForFinished();canvas->frame={};thumbs.clear();thumbQueue.clear();thumbPending.clear();workspace=std::make_unique<QTemporaryDir>(QDir::tempPath()+"/psd-native-XXXXXX");if(!workspace->isValid()){QMessageBox::critical(this,ui("打开失败"),ui("无法创建临时目录"));return;}doc={};doc.path=path;doc.workspace=workspace->path();baseline={};active=nullptr;selectionAnchor.clear();numbering.clear();numberingSelection.clear();refresh(true);setBusy(true);openClock.start();startCodec("open",{},[this](bool ok,QString error){if(ok){auto j=readObject(doc.workspace+"/document.json");doc.width=j["width"].toInt();doc.height=j["height"].toInt();doc.roots=loadLayers(j["children"].toArray());baseline=serializeLayers(doc.roots);recent.removeAll(doc.path);recent.prepend(doc.path);while(recent.size()>12)recent.removeLast();settings.setValue("recent-files",recent);refresh(true);naming();canvas->fit();}else{QMessageBox::critical(this,ui("打开失败"),error.left(1200));doc={};refresh(true);}setBusy(false);});}
void Window::select(Layer* n,bool checked){n->checked=checked;}
QVector<Layer*> Window::visibleLayers()const{QVector<Layer*> out;std::function<void(const Layers&)> walk=[&](const Layers& nodes){for(auto& n:nodes){auto index=model->forNode(n.get());if(tree->isRowHidden(index.row(),index.parent()))continue;out.append(n.get());if(n->group&&tree->isExpanded(index))walk(n->children);}};walk(doc.roots);return out;}
void Window::selectRow(Layer* node,Qt::KeyboardModifiers modifiers){
    bool control=modifiers.testFlag(Qt::ControlModifier),shift=modifiers.testFlag(Qt::ShiftModifier);auto flat=flatten(doc.roots);
    if(shift){auto visible=visibleLayers();int first=-1,last=visible.indexOf(node);for(int i=0;i<visible.size();++i)if(visible[i]->id==selectionAnchor)first=i;
        if(!control)for(auto n:flat)n->checked=false;
        if(first>=0&&last>=0){for(int i=qMin(first,last);i<=qMax(first,last);++i)visible[i]->checked=true;}else{node->checked=true;selectionAnchor=node->id;}
    }else if(control){node->checked=!node->checked;selectionAnchor=node->id;}
    else{for(auto n:flat)n->checked=n==node;selectionAnchor=node->id;}
    active=node;tree->setCurrentIndex(model->forNode(node));refresh();
}
void Window::createLayer(){
    auto layer=std::make_shared<Layer>();layer->id="layer-"+QUuid::createUuid().toString(QUuid::WithoutBraces);layer->name=layer->originalName=ui("新建图层");layer->manual=true;layer->blend="normal";
    Layer* target=active&&active->checked?active:nullptr;Layer* parent=target?(target->group?target:target->parent):nullptr;layer->parent=parent;auto& siblings=parent?parent->children:doc.roots;
    if(target&&!target->group){auto at=std::find_if(siblings.begin(),siblings.end(),[&](auto& n){return n.get()==target;});siblings.insert(at,layer);}else siblings.insert(siblings.begin(),layer);
    for(auto n:flatten(doc.roots))n->checked=n==layer.get();active=layer.get();selectionAnchor=layer->id;if(parent)parent->opened=true;refresh(true);tree->scrollTo(model->forNode(layer.get()));
}
void Window::visibility(Layer* n,bool hidden){n->hidden=hidden;for(auto& c:n->children)visibility(c.get(),hidden);}
void Window::expandAll(bool value){for(auto n:flatten(doc.roots))if(n->group){n->opened=value;tree->setExpanded(model->forNode(n),value);}}
QStringList Window::selectedLeaves()const{QStringList ids;for(auto n:flatten(doc.roots))if(n->checked&&!n->group)ids.append(n->id);return ids;}
void Window::number(){auto ids=selectedLeaves();if(ids.isEmpty())return;if(ids==numberingSelection&&!numbering.isEmpty()){for(auto n:flatten(doc.roots))if(numbering.contains(n->id)){n->name=numbering.value(n->id);n->manual=numberManual.value(n->id);}numbering.clear();numberManual.clear();numberingSelection.clear();}else{numbering.clear();numberManual.clear();numberingSelection=ids;bool letters=settings.value("numbering-style","numbers").toString()=="letters";auto suffix=[letters](int index){if(!letters)return QString::number(index);QString text;while(index>0){--index;text.prepend(QChar('A'+index%26));index/=26;}return text;};int i=1;for(auto n:flatten(doc.roots))if(ids.contains(n->id)){numbering.insert(n->id,n->name);numberManual.insert(n->id,n->manual);n->name+=settings.value("direction-separator","_").toString()+suffix(i++);n->manual=true;}}refresh();}
void Window::createGroup(){auto flat=flatten(doc.roots);auto leaves=selectedLeaves();Layer* layer=nullptr;Layer* parent=nullptr;for(auto n:flat){if(leaves.size()==1&&n->id==leaves.first())layer=n;if(!parent&&n->group&&n->checked)parent=n;}
    auto group=std::make_shared<Layer>();group->group=true;group->manual=true;group->checked=true;group->opened=true;group->blend="pass through";group->id="group-"+QUuid::createUuid().toString(QUuid::WithoutBraces);
    if(layer&&(!active||!active->group)){group->name=group->originalName=layer->name;auto& siblings=layer->parent?layer->parent->children:doc.roots;for(auto& n:siblings)if(n.get()==layer){group->parent=n->parent;group->children.push_back(n);n->parent=group.get();n=group;break;}}
    else{group->name=group->originalName=ui("新建组");group->parent=parent;auto& siblings=parent?parent->children:doc.roots;siblings.insert(siblings.begin(),group);if(parent)parent->opened=true;}
    for(auto n:flatten(doc.roots))n->checked=n==group.get();active=group.get();selectionAnchor=group->id;refresh(true);if(!layer)tree->edit(model->forNode(group.get()));}
void Window::deleteSelection(){
    if(busy)return;auto flat=flatten(doc.roots);QSet<Layer*> targets;QStringList names;int layers=0,groups=0;
    for(auto n:flat)if(n->checked){bool covered=false;for(auto parent=n->parent;parent;parent=parent->parent)if(parent->checked){covered=true;break;}if(covered)continue;targets.insert(n);names.append(n->name);for(auto child:flatten(n->children)){if(child->group)++groups;else ++layers;}}
    if(targets.isEmpty())return;QString question=ui("是否删除 %1 ？").arg(names.join(ui("、")));if(layers||groups)question+=ui("\n包含 %1 个图层、%2 个子文件夹").arg(layers).arg(groups);
    if(QMessageBox::question(this,ui("确认删除"),question,QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;
    std::function<void(Layers&)> remove=[&](Layers& nodes){std::erase_if(nodes,[&](auto& n){if(!targets.contains(n.get()))return false;thumbs.remove(n->id);thumbPending.remove(n->id);for(auto child:flatten(n->children)){thumbs.remove(child->id);thumbPending.remove(child->id);}return true;});for(auto& n:nodes)remove(n->children);};remove(doc.roots);active=nullptr;selectionAnchor.clear();numbering.clear();numberManual.clear();numberingSelection.clear();refresh(true);
}
bool Window::contains(Layer* parent,Layer* node)const{for(auto p=node;p;p=p->parent)if(p==parent)return true;return false;}
void Window::move(Layer* source,Layer* target,int place){if(!source||source==target||contains(source,target)||(place==0&&target&&!target->group))return;auto& old=source->parent?source->parent->children:doc.roots;auto it=std::find_if(old.begin(),old.end(),[&](auto& n){return n.get()==source;});if(it==old.end())return;auto owned=*it;old.erase(it);
    Layer* parent=target?(place==0?target:target->parent):nullptr;auto& nodes=parent?parent->children:doc.roots;source->parent=parent;if(target&&place){auto dest=std::find_if(nodes.begin(),nodes.end(),[&](auto& n){return n.get()==target;});if(place>0)++dest;nodes.insert(dest,owned);}else nodes.insert(nodes.begin(),owned);if(parent)parent->opened=true;refresh(true);naming();}
QImage* Window::thumb(Layer* n){if(!thumbnailsEnabled)return nullptr;if(auto found=thumbs.object(n->id))return found;if(!thumbPending.contains(n->id)&&!n->crop.isEmpty()){thumbPending.insert(n->id);thumbQueue.enqueue(n->id);thumbTimer.start();}return nullptr;}
void Window::preview(Layer* n){if(n->crop.isEmpty()){QMessageBox::information(this,n->name,ui("此图层无像素"));return;}auto image=thumbnail(doc,*n,1600);QDialog dialog(this);dialog.setWindowTitle(n->name);auto layout=new QVBoxLayout(&dialog);auto label=new QLabel(&dialog);label->setAlignment(Qt::AlignCenter);auto size=image.size().scaled(900,700,Qt::KeepAspectRatio);label->setPixmap(QPixmap::fromImage(image.scaled(size,Qt::KeepAspectRatio,Qt::SmoothTransformation)));layout->addWidget(label);auto close=button(ui("关闭"),&dialog);layout->addWidget(close,0,Qt::AlignRight);connect(close,&QPushButton::clicked,&dialog,&QDialog::accept);dialog.exec();}
void Window::closeEvent(QCloseEvent* e){if(busy){e->ignore();return;}settings.sync();e->accept();}
void Window::resizeEvent(QResizeEvent* e){if(isMaximized())clearMask();else{QPainterPath path;path.addRoundedRect(QRectF(rect()),8,8);setMask(QRegion(path.toFillPolygon().toPolygon()));}QWidget::resizeEvent(e);}
bool Window::nativeEvent(const QByteArray& type,void* message,qintptr* result){auto msg=static_cast<MSG*>(message);if(msg->message==WM_NCHITTEST&&!isMaximized()){RECT bounds;GetWindowRect(reinterpret_cast<HWND>(winId()),&bounds);int x=short(LOWORD(msg->lParam)),y=short(HIWORD(msg->lParam));int margin=qRound(6*devicePixelRatioF());bool left=x<bounds.left+margin,right=x>=bounds.right-margin,top=y<bounds.top+margin,bottom=y>=bounds.bottom-margin;int hit=top?(left?HTTOPLEFT:right?HTTOPRIGHT:HTTOP):bottom?(left?HTBOTTOMLEFT:right?HTBOTTOMRIGHT:HTBOTTOM):left?HTLEFT:right?HTRIGHT:HTCLIENT;if(hit!=HTCLIENT){*result=hit;return true;}}return QWidget::nativeEvent(type,message,result);}

void Window::setThumbnailsEnabled(bool enabled){thumbnailsEnabled=enabled;settings.setValue("thumbnails-enabled",enabled);thumbnailButton->setText(enabled?ui("关闭缩略图"):ui("显示缩略图"));thumbnailButton->setFixedWidth(QFontMetrics(thumbnailButton->font()).horizontalAdvance(thumbnailButton->text())+20);if(!enabled){thumbTimer.stop();thumbQueue.clear();thumbPending.clear();thumbs.clear();}int scroll=tree->verticalScrollBar()->value();tree->doItemsLayout();tree->verticalScrollBar()->setValue(scroll);tree->viewport()->update();}
void Window::setCanvasEnabled(bool enabled){if(canvasEnabled&&!enabled){savedSplitSizes=splitter->sizes();canvas->delay.stop();canvas->pending=false;++canvas->generation;canvas->frame={};}canvasEnabled=enabled;settings.setValue("canvas-enabled",enabled);canvasButton->setText(enabled?ui("关闭画布"):ui("显示画布"));canvasButton->setFixedWidth(QFontMetrics(canvasButton->font()).horizontalAdvance(canvasButton->text())+20);canvas->setVisible(enabled);if(enabled){if(!savedSplitSizes.isEmpty())splitter->setSizes(savedSplitSizes);canvas->request();}}

